// viewerEq compares two Viewers field-wise (Viewer carries slice/map fields,
// so it is not a comparable struct).
func viewerEq(a, b access.Viewer) bool {
	return a.Admin == b.Admin &&
		a.UserID == b.UserID &&
		slices.Equal(a.VisibleLibraryIDs, b.VisibleLibraryIDs) &&
		maps.Equal(a.ChainMutes, b.ChainMutes)
}

// seedViewerIdentity opens an api store with a LIVE accounts deployment on
// it: one user (so HasUsers is true and no legacy collapse fires) whose row
// id comes back, plus the identity service wired over the store — the
// identity resolve-test seeding pattern (groups + collections via the
// identity service, libraries via the store's own CreateLibrary).
func seedViewerIdentity(t *testing.T, st *store.Store, username string) (*identity.Service, int64) {
	t.Helper()
	s := identity.NewService(st, nil)
	u, err := s.Create(context.Background(), username, "pw")
	if err != nil {
		t.Fatalf("identity.Create %q: %v", username, err)
	}
	return s, u.ID
}

// seedLibrary creates one library through the store's own API (the LIVE
// intersection must hit a real libraries row).
func seedLibrary(t *testing.T, st *store.Store, root string) int64 {
	t.Helper()
	id, err := st.CreateLibrary(context.Background(), "testmod", root, root)
	if err != nil {
		t.Fatalf("CreateLibrary %q: %v", root, err)
	}
	return id
}

// viewerRequest builds a GET request carrying the given principal (the
// middleware's own stash key) — the direct-call shape of the mapping matrix.
func viewerRequest(p Principal) *http.Request {
	req := httptest.NewRequest(http.MethodGet, "/api/v1/libraries", nil)
	return req.WithContext(context.WithValue(req.Context(), principalKey{}, p))
}

// TestViewerForMapping is the D9 mapping matrix: viewerFor maps each
// principal kind (and each runtime posture) to its Viewer scope exactly
// once per request, stashing it for every downstream FromContext reader.
func TestViewerForMapping(t *testing.T) {
	t.Run("env_admin_admin_scope", func(t *testing.T) {
		st := openAPIStore(t)
		ident, _ := seedViewerIdentity(t, st, "alia") // users present: no collapse
		a := &app{deps: Deps{Store: st, Identity: ident}}

		v, ctx := a.viewerFor(viewerRequest(Principal{Role: RoleAdmin}))
		if !v.Admin || v.UserID != 0 || v.VisibleLibraryIDs != nil || v.ChainMutes != nil {
			t.Fatalf("env-admin viewer = %+v, want the all-seeing Admin scope", v)
		}
		// Exactly one stash, and it is THE carrier: downstream readers see
		// the same viewer.
		if !viewerEq(access.FromContext(ctx), v) {
			t.Fatalf("stashed viewer = %+v, want %+v", access.FromContext(ctx), v)
		}
	})

	t.Run("device_legacy_today", func(t *testing.T) {
		st := openAPIStore(t)
		ident, _ := seedViewerIdentity(t, st, "alia")
		a := &app{deps: Deps{Store: st, Identity: ident}}

		// Today's device principal carries no bound user (7.1 widens
		// Principal with the credential's UserID) — the unbound see-all
		// LegacyDevice posture, NOT the zero Viewer.
		v, _ := a.viewerFor(viewerRequest(Principal{Role: RoleClient}))
		if !v.Admin || v.UserID != 0 {
			t.Fatalf("device viewer = %+v, want LegacyDevice (see-all, slot 0)", v)
		}
	})

	t.Run("legacy_collapse_zero_users", func(t *testing.T) {
		st := openAPIStore(t)
		// Identity wired but NO users: the runtime-legacy collapse (D1) —
		// today's scope for EVERY principal, decided before any mapping.
		ident := identity.NewService(st, nil)
		a := &app{deps: Deps{Store: st, Identity: ident}}

		av, _ := a.viewerFor(viewerRequest(Principal{Role: RoleAdmin}))
		if !av.Admin {
			t.Fatalf("collapsed env-admin viewer = %+v, want Admin (as today)", av)
		}
		dv, _ := a.viewerFor(viewerRequest(Principal{Role: RoleClient}))
		if !dv.Admin || dv.UserID != 0 {
			t.Fatalf("collapsed device viewer = %+v, want LegacyDevice (as today)", dv)
		}
	})

	t.Run("nil_identity_legacy_no_panic", func(t *testing.T) {
		st := openAPIStore(t)
		// Nil Identity = runtime-legacy behavior (the nil-safe Deps
		// contract): ResolveViewer is never consulted — a non-nil service
		// is the only way this leg could panic, so the clean run IS the
		// proof nothing resolved.
		a := &app{deps: Deps{Store: st}}

		dv, _ := a.viewerFor(viewerRequest(Principal{Role: RoleClient}))
		if !dv.Admin || dv.UserID != 0 {
			t.Fatalf("nil-identity device viewer = %+v, want LegacyDevice", dv)
		}
		av, _ := a.viewerFor(viewerRequest(Principal{Role: RoleAdmin}))
		if !av.Admin {
			t.Fatalf("nil-identity env-admin viewer = %+v, want Admin", av)
		}
	})

	t.Run("resolve_shaped_viewer_through_seam", func(t *testing.T) {
		// The ResolveViewer-shaped scope (the 7.1 bound-device/session legs'
		// product) flows through the seam untouched: a real identity.Service
		// grant union, seeded via the seam's viewer injection
		// (principalViewerInjector — the same carrier viewerFor memoizes),
		// comes back from viewerFor byte-faithful.
		st := openAPIStore(t)
		ident, uid := seedViewerIdentity(t, st, "alia")
		l1 := seedLibrary(t, st, "/lib/one")
		l2 := seedLibrary(t, st, "/lib/two")
		if _, err := ident.CreateGroup(context.Background(), "Movies"); err != nil {
			t.Fatalf("CreateGroup: %v", err)
		}
		if err := ident.AddCollection(context.Background(), "Movies", l1, 0); err != nil {
			t.Fatalf("AddCollection l1: %v", err)
		}
		if err := ident.AddCollection(context.Background(), "Movies", l2, 1); err != nil {
			t.Fatalf("AddCollection l2: %v", err)
		}
		if err := ident.AddUser(context.Background(), "Movies", "alia"); err != nil {
			t.Fatalf("AddUser: %v", err)
		}
		want, err := ident.ResolveViewer(context.Background(), uid, false)
		if err != nil {
			t.Fatalf("ResolveViewer: %v", err)
		}

		a := &app{deps: Deps{Store: st, Identity: ident}}
		r := chi.NewRouter()
		r.Use(principalViewerInjector(want))
		r.Get("/probe", func(w http.ResponseWriter, req *http.Request) {
			v, ctx := a.viewerFor(req)
			if !viewerEq(v, want) {
				t.Errorf("viewer through the seam = %+v, want the resolved grant union %+v", v, want)
			}
			if !viewerEq(access.FromContext(ctx), want) {
				t.Errorf("stashed viewer = %+v, want %+v", access.FromContext(ctx), want)
			}
			// The seam's stash IS the memo: the request's context came back
			// unchanged — no second resolve, no second WithViewer.
			if ctx != req.Context() {
				t.Errorf("viewerFor re-stashed an already-stashed context")
			}
			_ = json.NewEncoder(w).Encode(map[string]bool{"ok": true})
		})
		resp := doRequest(t, r, http.MethodGet, "/probe", "", adminToken)
		resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("probe status = %d, want 200", resp.StatusCode)
		}
	})

	t.Run("memo_one_resolve_one_stash", func(t *testing.T) {
		// Behavioral memo proof: between the first and second viewerFor calls
		// the user's grant set GROWS — the second call must still return the
		// first call's set (read from the stash, not re-resolved) and the
		// same context instance (no second stash).
		st := openAPIStore(t)
		ident, uid := seedViewerIdentity(t, st, "alia")
		l1 := seedLibrary(t, st, "/lib/one")
		l2 := seedLibrary(t, st, "/lib/two")
		if _, err := ident.CreateGroup(context.Background(), "Movies"); err != nil {
			t.Fatalf("CreateGroup: %v", err)
		}
		if err := ident.AddCollection(context.Background(), "Movies", l1, 0); err != nil {
			t.Fatalf("AddCollection l1: %v", err)
		}
		if err := ident.AddUser(context.Background(), "Movies", "alia"); err != nil {
			t.Fatalf("AddUser: %v", err)
		}

		// The memo is keyed on the carrier, and today's device principal is
		// the LegacyDevice leg — so the memoized scope rides an injected
		// scoped viewer (exactly what the seam and 7.1's principals carry).
		want := access.User(uid, []int64{l1}, nil)
		req := viewerRequest(Principal{Role: RoleClient})
		req = req.WithContext(access.WithViewer(req.Context(), want))
		a := &app{deps: Deps{Store: st, Identity: ident}}

		v1, ctx1 := a.viewerFor(req)
		if !viewerEq(v1, want) {
			t.Fatalf("first viewerFor = %+v, want %+v", v1, want)
		}
		if !viewerEq(access.FromContext(ctx1), want) {
			t.Fatalf("first stash read-back = %+v, want %+v", access.FromContext(ctx1), want)
		}

		// The grant set grows AFTER the first resolution: l2 joins Movies.
		if err := ident.AddCollection(context.Background(), "Movies", l2, 1); err != nil {
			t.Fatalf("AddCollection l2: %v", err)
		}

		v2, ctx2 := a.viewerFor(req.WithContext(ctx1))
		if !viewerEq(v2, v1) {
			t.Fatalf("second viewerFor re-resolved: got %+v, want the memoized %+v (grants changed underneath)", v2, v1)
		}
		if ctx2 != ctx1 {
			t.Fatalf("second viewerFor re-stashed: context identity changed")
		}
	})
}
